magic_header = b"cIMG"
version = 3
create_code = 3
render_code = 4

doa = [desired_output[s:s+24] for s in range(0,len(desired_output),24)]
pixel = [(int(p[7:10]),int(p[11:14]),int(p[15:18]),p[19]) for p in doa]


"""Calculate width of image"""
count = 0
for i,p in enumerate(pixel):
    x,y,z,c = p
    if c == ".":
        count += 1
    if count == 2:
        width = i+1
        print("Length: ",i+1)
        print("Height: ",len(pixel)/(i+1))
        break
height = len(pixel)//width

def header(dir):
    return magic_header+struct.pack("<HBBI",version,width,height,dir)

directive = []
sprite_id = 0

def return_pixel_color(x,y):
    index = width * y + x
    r,g,b,c = pixel[index]
    return (r,g,b)

def sprite_creater(sprite_id,w,h,data):
    payload = struct.pack("<HBBB",create_code,sprite_id,w,h)+data.encode()
    directive.append(payload)

def render_creater(id,color,x,y):
   r,g,b = color
   payload = struct.pack("<HBBBBBB",render_code,id,r,g,b,x,y)
   directive.append(payload)

white = return_pixel_color(0,0)
sprite_creater(sprite_id,37,1,"-"*37)
render_creater(sprite_id,white,1,0)
render_creater(sprite_id,white,38,0)
render_creater(sprite_id,white,1,height-1)
render_creater(sprite_id,white,38,height-1)

sprite_id += 1
sprite_creater(sprite_id,1,22,"|"*22)
render_creater(sprite_id,white,0,1)
render_creater(sprite_id,white,width-1,1)

sprite_id += 1
sprite_creater(sprite_id,1,1,".")
render_creater(sprite_id,white,0,0)
render_creater(sprite_id,white,width-1,0)

sprite_id += 1
sprite_creater(sprite_id,1,1,"'")
render_creater(sprite_id,white,0,height-1)
render_creater(sprite_id,white,width-1,height-1)

def seperate_logo_by_color():
    color_char = {}
    for i in range(1,height-1):
        for j in range(1,width-1):
            r,g,b,c = pixel[width*i+j]
            if c != " ":
                color = (r,g,b)
                color_char.setdefault(color,[]).append((j,i,c))
    return color_char
color_char = seperate_logo_by_color()
print(color_char)

def make_sprite_for_logo():
    global sprite_id
    combination = color_char.keys()
    for color in combination:
        characters = color_char[color]
        min_x,min_y = min(p[0] for p in characters),min(p[1] for p in characters)
        max_x,max_y = max(p[0] for p in characters),max(p[1] for p in characters)
        sprite_width = max_x - min_x + 1
        sprite_height = max_y - min_y + 1
        grid = [" "]*(sprite_width*sprite_height)
        for c in characters:
            index = (c[1] - min_y) * sprite_width + (c[0] - min_x)
            grid[index] = c[2]
        sprite_id += 1
        sprite_creater(sprite_id,sprite_width,sprite_height,"".join(grid))
        render_creater(sprite_id,color,min_x,min_y)

make_sprite_for_logo()

payload = header(len(directive)) + b"".join(directive)

print("Used Directive: ",len(directive))
print("Payload length: ",len(payload))

with open("image.cimg","wb") as file:
    file.write(payload)

io = process(["/challenge/cimg","image.cimg"])
io.interactive()
